            MTRErrorCallback failureCb, MTRCallbackBridgeBase * bridge) {
            using TypeInfo = OnOff::Attributes::OnOff::TypeInfo;
            chip::Controller::OnOffCluster cppCluster(exchangeManager, session, self->_endpoint);
