            MTRErrorCallback failureCb, MTRCallbackBridgeBase * bridge) {
            using TypeInfo = MediaInput::Attributes::InputList::TypeInfo;
            chip::Controller::MediaInputCluster cppCluster(exchangeManager, session, self->_endpoint);
